from __future__ import absolute_import, annotations

import logging
from typing import Union

from taf.config.testline.pdu import Pdu as PduModel
from taf.internal.aliasing import aliasing_scope
from taf.internal.contracts import PduConfig, contract_consumer
from taf.internal.robot_typecasts import time_to_seconds

from .devices.base import PDU as PduBase, PduIdentInfo
from .facade import PduFacade


class pdu(object):
    """
    This library provides basic PDU keywords: power on given port,
    power off given port, reset given ports, get port status.

    After setting up a PDU device with an ``alias`` string, one can use that alias
    in place of ``pdu_device`` argument for every keyword except ``setup_pdu``.
    One can also use pdu device object in place of ``pdu_device`` argument,
    which is returned by ``setup_pdu`` keyword.

    Supported models are listed in ``setup_pdu`` documentation.

    **Note for ATEN devices**:
    Status change for a port is not possible if a port is in 'pending' state.
    With that in mind, reasonable time interval should be provided when
    calling `reset_ports`. Ten seconds were empirically proven to be enough.
    Commands are sent by SNMP protocol so this option should be enabled on PDU.

    **Note for FACOM devices**:
    Port number should be in range [1, 8].

    **Note for RRB devices**:
    Port number should start from 1. This ordering conforms to web interface's
    serial number ordering.
    Exception is NOT raised when trying to set port to a status that it is already in.
    Port number is NOT checked when setting its status. It is checked when one is
    getting port status.

    **Note for APC devices**:
    By default port numbers in range [1, 8] are supported
    If the APC device has different amount of ports then a call to a specific model or
    passing num_of_ports parameter is required
    After changing port status, one should wait up to a second before checking
    port status to make sure that APC server won't respond with incorrect status.
    Commands are sent by SNMP protocol so this option should be enabled on PDU.

    **Note for Gude (EPC, EPC 1202-1, EPC 8221-1, EPC 8226-1) devices**:
    Commands are sent by SNMP protocol so this option should be enabled on PDU.
    In EPC WebUI you can do it in:
    Configuration --> SNMP --> SNMP-get and SNMP-set --> apply

    **Note for PKC devices**:
    Port number should be in range [1, 8].
    Commands are sent by telnet protocol so this option should be configured on PDU.

    **Note for UTRONIX devices**:
    Port number should be in range [1, 8].
    Commands are sent by http protocol so this option should be configured on PDU.

    **Note for DigiPower devices**:
    Port number should be in range [1, 8].
    Commands are sent by http protocol so this option should be configured on PDU.

    **Note for Lantick devices**:
    Port number should be in range [1, 8].
    Commands are sent by http protocol so this option should be configured on PDU.

    **Note for PS9000 devices**:
    Port number is unnecessary, defaults to only available option: Literal[1].
    Commands are sent by http protocol so this option should be configured on PDU.

    **Note for HPE devices**:
    Port number should be in range [1, 24].
    Commands are sent by SNMPv3 protocol so this option should be enabled on PDU.

    **Note for PSE544 blackbox pdutype devices**:
    Port number should be in range [1, 4].
    Commands are sent by SNMPv3 protocol so this option should be configured on PDU.

    **Note for TDK Lambda devices**:
    The device has only one port, so by the rule it should be a string "1"
    (the port value is ignored).
    It was reported that the device may not always connect the first time,
    so the setup_pdu will try twice to setup the connection.

    **Note for PSU, Keysight, Kikusui devices**:
    Port number is unnecessary, values are ignored, defaults to only available option.
    Commands are sent by scpi protocol, telnet option should be configured on PDU.

    **Note for PSI devices**:
    Port number is unnecessary, values are ignored, defaults to only available option.

    **Note for DeltaElektronika devices**:
    The device has default port 8462.
    Commands are sent by scpi protocol, telnet option should be configured on PDU.

    **Note for devices using snmpv3 protocol**:
    It is recommended to run under Python >= 3.7 when testing such devices.
    """

    ROBOT_LIBRARY_SCOPE = "TEST SUITE"

    lookup_handler, configured_pdus = aliasing_scope(name=__name__, lookup_arg="pdu_device", lookup_type=PduBase)

    def __init__(self):
        self._facade = PduFacade()

    @contract_consumer(robot_name="Setup Pdu: ${contract_data: [^(]+} (aliased as ${alias})")
    def configure_pdu_connection(self, contract_data: PduConfig, alias=None):
        """
        Configure connection to a PDU device.

        .. note::
            **The name of this keyword in Robot Framework differs from its Python
            method name.** In Python, it is called
            :py:func:`configure_pdu_connection`. In Robot Framework, the usage
            starts with ``Setup Pdu: ...``. See the example below.

        **Robot Framework Example**::

            Setup Pdu: ${tl.gnbs[0].dus[0].airscale.common_units[0].pdu_port.pdu} (aliased as cu_pdu)

        .. tip::
            ✨ This keyword should be used with objects that support
            `PDU Contract <https://taf-internal-contracts.docs.taf.ute.nsn-rdnet.net/
            en/latest/api/reference.html#taf.internal.contracts.Pdu>`_ ✨

            For a list of test line configuration classes that support this contract,
            see `Contracts Reference in taf.config.testline <https://
            taf-config-testline.docs.taf.ute.nsn-rdnet.net/en/latest/contracts.html>`_.

        :param contract_data: PDU connection configuration data
        :param str alias: alias to be used in keywords
        """
        return self.setup_pdu(
            model=contract_data["model"],
            host=contract_data["addr"],
            alias=alias,
            **contract_data["model_specific_parameters"],
        )

    def setup_pdu(
        self, model: Union[PduModel, str], host: str | None = None, alias: str | None = None, **kwargs
    ) -> PduBase:
        """
        Prepare library to work with specified PDU device.

        :param Union[PduModel, str] model: pdu device to create.
            If it is a string, it is assumed to represent a vendor.
            In that case, ``version`` can also be specified, e.g.,
            ``model=GUDE, version=8226-1``. Otherwise, it is assumed to be
            a Pdu object from `taf.config.testline`. In that case the
            program can differentiate vendor, model and version of the
            Pdu. Currently, supported vendors with their respective
            models and versions are:

            - APC models: default, AP7922B

            - ATEN models: default

            - EPC (deprecated, will be removed in version 2.0.0) models:
              default

            - FACOM models: default

            - HBTE models: default

            - RRB models: default

            - PKC models: default, 16

            - UTRONIX models: default

            - OSP models: default

            - GUDE models: (See EPC or ENC)

            - EPC versioned devices: default, 8220-1, 1202-1, 8221-1, 8225-1,
              8226-1, 8041-1

            - ENC versioned devices: default, 2304

            - TOPYOUNG models: default, RTS-C003-186

            - DigiPower models: default

            - Lantick models: default

            - PS9000 models: default

            - HPE models: default

            - FPFH models: default

            - TdkLambda: default

            - PSU: default

            - APP6: default, MULTI (2 devices in series under a single IP)

            - BKT: default

            - IPOWER: default

            - FAC: default

            - EPCNC: 8220-1 (default), 8221-1

            - Keysight: N5767A N8757A

            - ElektroAutomatik: PS9080-100, PS9060-170, PSI10060-120

            - Kikusui: default

            - DeltaElektronika: SM3300 (default)

            - Zentronics: ZSPSU48D (default), ZS40DCB16i-V, PDU8P30A8B

            **Vendor, model, and version strings are case-insensitive.**

        :param str host: ip address or hostname of pdu device

            TdkLambda:
                The `host` parameter is used as a name of the
                serial port, that is used for connection. Example: COM1

        :param str alias: alias to be used in keywords
        :param str version: (optional) specifies version of the device,
            currently applicable to GUDE and TOPYOUNG
        :param kwargs: device specific parameters

            ATEN:
                **timeout** (float): response timeout in seconds
                    for connection with pdu device, default value is 30.
                **snmp_user** (dict): Account configuration for SNMPv3
                    with keys: ``userName``, ``authKey``, ``privKey``,
                    ``authProtocol`` (SHA/MD5), ``privProtocol`` (AES/DES)

            EPC, EPC 8220-1, EPC 8221-1, EPC 8225-1 and EPC 8226-1:
                **num_of_ports** (int): number of ports in EPC device,
                    default value is 12.
                **timeout** (float): response timeout in seconds for
                    connection with pdu device, default value is 1.

            EPC 1202-1:
                **num_of_ports** (int): number of ports in EPC
                    device, default value is 4.
                **timeout** (float): response timeout
                    in seconds for connection with pdu device,
                    default value is 1.

            EPC 8221-1, EPC 8226-1, EPC 8041-1:
                **num_of_ports** (int): number of ports in EPC
                    device, default value is 12.
                **timeout** (float): response timeout
                    in seconds for connection with pdu device,
                    default value is 1.
                **snmp_user** (dict): Account configuration for SNMPv3
                    with keys: ``userName``, ``authKey``, ``privKey``,
                    ``authProtocol`` (SHA/MD5), ``privProtocol`` (AES/DES)

            EPCNC 8220-1, EPCNC 8221-1:
                same as EPC counterparts

            ENC 2304:
                **num_of_ports** (int): number of ports in ENC
                    device, default value is 8.
                **timeout** (float): response timeout
                    in seconds for connection with pdu device,
                    default value is 1.
                **snmp_user** (dict): Account configuration for SNMPv3
                    with keys: ``userName``, ``authKey``, ``privKey``,
                    ``authProtocol`` (SHA/MD5), ``privProtocol`` (AES/DES)

            FACOM:
                **port** (int): port number for TCP connection.

                **timeout** (float): timeout in seconds for
                    establishing connection with a device.
                    Defaults to 10 seconds.

                Raises ``Timeout`` exception if timeout is exceeded.

                **retry_timeout** (float): timeout in seconds
                    for repeatedly trying to receive data from device
                    in 2-seconds intervals. Defaults to 5 seconds.

                Raises ``PduConnectionError`` if timeout is exceeded.

            HBTE:
                **port** (int): port number for TCP connection.

            RRB:
                **timeout** (float): How many seconds to wait for
                    the server to send data before giving up,
                    defaults to 30 seconds.

            APC:
                **timeout** (float): How many seconds to wait for
                    the server to send data before giving up,
                    defaults to 10 seconds.
                **snmp_user** (dict): Account configuration for
                    SNMPv3 with keys: ``userName``, ``authKey``, ``privKey``,
                    ``authProtocol`` (SHA/MD5), ``privProtocol`` (AES/DES)
                **num_of_ports** (int): number of ports in
                    APC device, default value is 8.

            PKC:
                **port** (int): port number for TCP connection.

                **timeout** (float): How many seconds to wait for
                    the server to send data before giving up,
                    defaults to 10 seconds.

            UTRONIX:
                **timeout** (float): response timeout in seconds for
                    connection with pdu device, default value is 10.

            OSP:
                **timeout** (float): How many seconds to wait for the
                    server to send data before giving up,
                    defaults to 10 seconds.

            TOPYOUNG:
                **timeout** (float): timeout in seconds for
                    establishing connection with a device.
                    Defaults to 10 seconds.

                Raises ``PduConnectionError`` if timeout is exceeded.

                **retry_timeout** (float): timeout in seconds for
                    repeatedly trying to receive data from device
                    in 2-seconds intervals. Defaults to 5 seconds.

                Raises ``Timeout`` exception if timeout is exceeded.

            DigiPower:
                **login** (string): username to login into the server.

                **password** (string): password to login
                    into the server.
                **timeout** (float): timeout in seconds for
                    establishing connection with a device.
                    Defaults to 20 seconds.

            Lantick:
                **login** (string): username to login into the server.

                **password** (string): password to login
                    into the server.
                **timeout** (float): timeout in seconds for
                    establishing connection with a device.
                    Defaults to 20 seconds.

            PS9000:
                **ip** (string): ip for TCP connection.

                **port** (int): port number for TCP connection.

            HPE:
                **timeout** (float): How many seconds to wait for
                    the server to send data before giving up,
                    defaults to 10 seconds.
                **snmp_user** (dict): Account configuration for
                    SNMPv3 with keys: ``userName``, ``authKey``, ``privKey``,
                    ``authProtocol`` (SHA/MD5), ``privProtocol`` (AES/DES)

            FPFH:
                **timeout** (float): How many seconds to wait for
                    the server to send data before giving up,
                    defaults to 10 seconds.
                **snmp_user** (dict): Account configuration for
                    SNMPv3 with keys: ``userName``, ``authKey``, ``privKey``,
                    ``authProtocol`` (SHA/MD5), ``privProtocol`` (AES/DES)
                **protocol** (str): Protocol for FPFH PDU.
                    Available protocols: 'snmp', 'http'

            TdkLambda:
                **timeout** (float): Set a read timeout
                    value is seconds, defaults to 30
                **write_timeout** (float): Set a write timeout
                    value is seconds, defaults to 30

            PSU:
                **timeout** (float): How many seconds to wait for
                    the server to send data before giving up,
                    defaults to 10 seconds.

            APP6:
                **timeout** (float): How many seconds to wait for
                    the server to send data before giving up,
                    defaults to 10 seconds.

            BKT:
                **timeout** (float): How many seconds to wait for
                    the server to send data before giving up,
                    defaults to 10 seconds.
                **community** (string): community name when
                    SNMP version 1 or version 2c used
                **snmp_user** (dict): Account configuration for SNMPv3
                    with keys: ``userName``, ``authKey``, ``privKey``,
                    ``authProtocol`` (SHA/MD5), ``privProtocol`` (AES/DES)

            IPOWER:
                **timeout** (float): How many seconds to wait for
                    the server to send data before giving up,
                    defaults to 10 seconds.
                **community** (string): community write name when
                    SNMP version 1 or version 2c used,
                    the SNMP read community name cannot be configured
                    the same as the write community name
                **snmp_user** (dict): Account configuration for SNMPv3
                    with keys: ``userName``, ``authKey``, ``privKey``,
                    ``authProtocol`` (SHA/MD5), ``privProtocol`` (AES/DES)

            FAC:
                **timeout** (float): How many seconds to wait for
                    the server to send data before giving up,
                    default is 30 seconds.
                **community** (string): community write name when
                    SNMP version 1 or version 2c used,
                    the SNMP read community name cannot be configured
                    the same as the write community name
                **snmp_user** (dict): Account configuration for SNMPv3
                    with keys: ``userName``, ``authKey``, ``privKey``,
                    ``authProtocol`` (SHA/MD5), ``privProtocol`` (AES/DES)

        :return: configured pdu object
        """
        if host is None:
            try:
                host = model.addr  # type: ignore[union-attr]
            except AttributeError:
                raise TypeError("host argument is missing")

        timeout = kwargs.get("timeout", None)
        if timeout:
            kwargs["timeout"] = time_to_seconds(timeout)
        configured_pdu = self._facade.setup_pdu(model=model, host=host, **kwargs)
        self.configured_pdus.add(configured_pdu, alias)
        return configured_pdu

    @lookup_handler.implicit_lookup
    def power_on(self, port, pdu_device=None):
        """
        Powers ON given port on given pdu device.

        :param int or PduPort port: port number, starting from 1 or PduPort object of relevant port
        :param str pdu_device: alias of configured pdu
        """
        logging.info(f"Powering on port: {port}")
        return self._facade.power_on(port=port, pdu_device=pdu_device)

    @lookup_handler.implicit_lookup
    def power_off(self, port, pdu_device=None):
        """
        Powers OFF given port on given pdu device.

        :param int or PduPort port: port number, starting from 1 or PduPort object of relevant port
        :param str pdu_device: alias of configured pdu
        """
        logging.info(f"Powering off port: {port}")
        return self._facade.power_off(port=port, pdu_device=pdu_device)

    @lookup_handler.implicit_lookup
    def get_port_status(self, port, pdu_device=None):
        """
        Get status of given port for given pdu device.

        :param int port: port number, starting from 1
        :param str pdu_device: alias of configured pdu
        :return: string 'on', 'off'. For BlackBox devices can return 'reset' if the port is in resetting state.
        """
        logging.info(f"Getting status of port: {port}")
        return self._facade.get_port_status(port=port, pdu_device=pdu_device)

    @lookup_handler.implicit_lookup
    def get_voltage(self, pdu_device=None, port=None):
        """
        Get voltage from PDU

        .. note::
            Keyword implemented only for selected devices

        :param int port: port (power outlet) number
        :param str pdu_device: alias of configured pdu
        :return: voltage on PDU port in volts (V)
        :rtype: float
        """
        return self._facade.get_voltage(pdu_device=pdu_device, port=port)

    @lookup_handler.implicit_lookup
    def set_voltage(self, port, voltage=None, pdu_device=None):
        """
        Set voltage on given pdu device.

        :param int port: port number, starting from 1
        :param float voltage: new output voltage supply
        :param str pdu_device: alias of configured pdu
        """
        logging.info(f"Setting voltage: {voltage}")
        return self._facade.set_voltage(port=int(port), voltage=float(voltage), pdu_device=pdu_device)

    @lookup_handler.implicit_lookup
    def reset_ports(self, ports=None, time_interval=10, pdu_device=None):
        """
        Powers OFF given ports, waits a number of seconds and powers ON given ports.
        This keyword does not check for a port status before on/off actions.

        :param list ports: list of port numbers, type: int or PduPort,
                           every port number should start from 1, None by default indicates all ports in topyoung
        :param int time_interval: number of seconds
                                  to wait between OFF/ON actions, defaults to 10
        :param str pdu_device: alias of configured pdu
        """
        logging.info(f"Resetting ports: {ports}")
        return self._facade.reset_ports(ports=ports or [], pdu_device=pdu_device, time_interval=int(time_interval))

    @lookup_handler.implicit_lookup
    def teardown_pdu(self, pdu_device=None):
        """
        Perform a teardown operation provided that a specific device defines one.

        .. note::
            Keyword implemented only for selected devices

        :param str pdu_device: alias of configured pdu
        """
        return self._facade.teardown_pdu(pdu_device)

    @lookup_handler.implicit_lookup
    def get_current(self, port, pdu_device=None):
        """
        Get output current value for a given power outlet (port)

        .. note::
            Keyword implemented only for selected devices

        :param int port: port number
        :param str pdu_device: alias of configured pdu
        :return: electric current value in amperes (A)
        :rtype: float
        """
        return self._facade.get_current(port, pdu_device)

    @lookup_handler.implicit_lookup
    def get_energy_consumption(self, port, pdu_device=None):
        """
        Get total power consumption for a given power outlet (port)

        .. note::
            Keyword implemented only for selected devices

        :param int port: port number
        :param str pdu_device: alias of configured pdu
        :return: total energy consumption in kilowatt-hours (kWh)
        :rtype: float
        """
        return self._facade.get_energy_consumption(port, pdu_device)

    @lookup_handler.implicit_lookup
    def get_pdu_info(self, pdu_device=None) -> PduIdentInfo:
        """
        Get identification information for a PDU device.

        - For SCPI-capable devices, returns the raw response of `*IDN?` and
          sets identification_type to SCPI_IDN.
        - For devices that do not implement identification, returns
          identifier "UNKNOWN" with identification_type NOT_IMPLEMENTED.

        :param str pdu_device: alias of configured pdu
        :return: PduIdentInfo(identifier, identification_type)
        :rtype: PduIdentInfo
        """
        logging.info("Getting PDU identification info")
        return self._facade.get_pdu_info(pdu_device)
